# System-specific configuration for Orion
#
# This file contains machine-specific settings like user preferences,
# application choices, and local configuration.
#
# Network configuration (IPs, MACs, SSH) is centralized in fleet-config.nix
let
  # Import centralized network configuration
  networkConfig = import ../../fleet-config.nix;
  # Get this host's network settings
  thisHost = networkConfig.hosts.orion;
in
{
  system = {
    hostName = thisHost.hostname; # From fleet-config.nix
    # Machine-specific settings
    # Add other system-level configs here
  };

  user = {
    username = "syg";

    # Which compositor is in use (used by swhkd for lock screen selection)
    # Options: "Hyprland", "niri"
    compositor = "niri";

    git = {
      username = "sygint";
      email = "sygint@users.noreply.github.com";
    };

    hyprland = {
      terminal = "ghostty";
      fileManager = "nemo";
      webBrowser = "brave";
      menu = "noctalia-shell ipc call launcher toggle";
      bar = "hyprpanel"; # or "waybar"
    };
  };

  # Monitor configuration
  # Layout: Laptop on top, ultrawide below, portrait monitor on right
  #
  #     ┌─────────────┐
  #     │   Laptop    │ (2256x1504)
  #     │   (top)     │
  #     └─────────────┘
  #     ┌───────────────────────┐ ┌──────┐
  #     │      Ultrawide        │ │Portr.│ (1080x1920)
  #     │       (3440)          │ │      │
  #     └───────────────────────┘ └──────┘
  #
  # Using description matching for stable identification across reboots/ports
  # Full "manufacturer model serial" from EDID — works for both compositors:
  #   Niri: exact match on "manufacturer model serial" (run `niri msg outputs`)
  #   Hyprland: substring match with `desc:` prefix (run `hyprctl monitors`)
  monitors = [
    # Laptop display (BOE panel)
    {
      desc = "BOE 0x0BCA Unknown";
      resolution = "2256x1504@60";
      position = "0x0";
      scale = "1";
    }
    # Acer ultrawide - below laptop
    {
      desc = "Acer Technologies ED343CUR V 1326001BF2X00";
      resolution = "3440x1440@60";
      position = "0x1504";
      scale = "1";
    }
    # Sceptre portrait monitor - right side, bottom-aligned with ultrawide
    {
      desc = "Sceptre Tech Inc Sceptre M24 00";
      resolution = "1920x1080@165";
      position = "3440x1024";
      scale = "1";
      transform = "1"; # 90° rotation
    }
  ];

  # Workspace configuration (shared across compositors)
  # Each workspace has a name and optional compositor-specific settings.
  # - hyprland: id (required), monitorDesc for monitor pinning
  # - niri: rule for workspace rules
  # The first workspace assigned to each monitor gets default:true automatically (Hyprland).
  workspaces = [
    # Ultrawide (Main)
    { name = "System"; hyprland = { id = 1;  monitorDesc = "Acer Technologies ED343CUR V 1326001BF2X00"; }; niri = { rule = "open-on-output=Acer Technologies ED343CUR V 1326001BF2X00"; }; }
    { name = "ES";     hyprland = { id = 2;  monitorDesc = "Acer Technologies ED343CUR V 1326001BF2X00"; }; niri = { rule = "open-on-output=Acer Technologies ED343CUR V 1326001BF2X00"; }; }
    { name = "HSFF";   hyprland = { id = 3;  monitorDesc = "Acer Technologies ED343CUR V 1326001BF2X00"; }; niri = { rule = "open-on-output=Acer Technologies ED343CUR V 1326001BF2X00"; }; }
    { name = "PRJ";    hyprland = { id = 4;  monitorDesc = "Acer Technologies ED343CUR V 1326001BF2X00"; }; niri = { rule = "open-on-output=Acer Technologies ED343CUR V 1326001BF2X00"; }; }
    { name = "PRJ2";   hyprland = { id = 5;  monitorDesc = "Acer Technologies ED343CUR V 1326001BF2X00"; }; niri = { rule = "open-on-output=Acer Technologies ED343CUR V 1326001BF2X00"; }; }
    # Laptop (Secondary)
    { name = "Media";   hyprland = { id = 6;  monitorDesc = "BOE 0x0BCA"; }; niri = { rule = "open-on-output=BOE 0x0BCA Unknown"; }; }
    { name = "Media 2"; hyprland = { id = 7;  monitorDesc = "BOE 0x0BCA"; }; niri = { rule = "open-on-output=BOE 0x0BCA Unknown"; }; }
    # Portrait (Tertiary)
    { name = "Chat"; hyprland = { id = 8;  monitorDesc = "Sceptre Tech Inc Sceptre M24 00"; }; niri = { rule = "open-on-output=Sceptre Tech Inc Sceptre M24 00"; }; }
    { name = "Info"; hyprland = { id = 9;  monitorDesc = "Sceptre Tech Inc Sceptre M24 00"; }; niri = { rule = "open-on-output=Sceptre Tech Inc Sceptre M24 00"; }; }
  ];

  # Re-export network config for this host (optional, for convenience)
  network = thisHost;
}

{
  pkgs,
  config,
  inputs,
  ...
}:
let
  inherit (config.lib.file) mkOutOfStoreSymlink;
in
{
  imports = [
    ../../../modules/home
    ./extra-programs.nix
  ];

  home.packages = with pkgs; [
    rofi
  ];

  # Make the monitor-setup script available in the user's PATH by
  # adding it to $HOME/bin via home.file. This avoids injecting the
  # script into system evaluation and keeps it available for interactive
  # sessions and user-level automation. The inline script prefers a
  # monitors.json in $HOME/.config/nixos/monitors.json or $HOME/.config/monitors.json
  home.file."bin/monitor-setup" = {
    text = ''
      #!/usr/bin/env bash
          set -euo pipefail

          MONITORS_JSON=""
          for path in "$HOME/.config/nixos/monitors.json" "$HOME/.config/monitors.json" "/etc/monitors.json"; do
            if [ -f "$path" ]; then MONITORS_JSON="$path"; break; fi
          done

          if [ -z "$WAYLAND_DISPLAY" ] && [ -z "$DISPLAY" ] && [ -z "$XDG_RUNTIME_DIR" ]; then
            echo "No graphical display detected; skipping monitor setup."
            exit 0
          fi

          if ! command -v hyprctl >/dev/null 2>&1; then
            echo "hyprctl not found; skipping monitor setup." >&2
            exit 0
          fi
          if ! command -v jq >/dev/null 2>&1; then
            echo "jq not found; skipping monitor setup." >&2
            exit 0
          fi

          if [ -z "$MONITORS_JSON" ]; then
            echo "No monitors.json found in standard locations; nothing to configure." >&2
            exit 0
          fi

          names="$(hyprctl monitors -j | jq -r '.[].name')"
          count="$(printf "%s\n" "$names" | wc -l | tr -d ' ')"
          if [ "$count" -eq 0 ]; then
            echo "No monitors detected; skipping." >&2
            exit 0
          fi

          while IFS= read -r name; do
            if jq -e --arg n "$name" 'has($n)' "$MONITORS_JSON" >/dev/null; then
              config="$(jq -r --arg n "$name" '.[$n]' "$MONITORS_JSON")"
              echo "Applying monitor config for $name: $config"
              hyprctl keyword monitor "$name, $config" || echo "Failed to apply config for $name"
            else
              echo "No config found for monitor: $name" >&2
            fi
          done <<< "$names"

    '';
    executable = true;
  };

  # All programs now managed by unified features modules in system config
  # - hyprland, hyprpanel, waybar, hypridle, screenshots
  # - git, kitty, btop, devenv, vscode
  # - brave, firefox, librewolf
  # - archiver, protonmail-bridge
  # - mullvad

  # Declarative Flatpak management
  services.flatpak = {
    enable = true;
    packages = [
      "us.zoom.Zoom"
    ];
    update = {
      onActivation = false; # Don't auto-update on every rebuild
      auto = {
        enable = true;
        onCalendar = "weekly"; # Auto-update weekly
      };
    };
  };

  # Add Flatpak directories to XDG_DATA_DIRS so apps appear in Rofi
  home.sessionVariables = {
    XDG_DATA_DIRS = "$XDG_DATA_DIRS:/var/lib/flatpak/exports/share:$HOME/.local/share/flatpak/exports/share";
  };

  # OpenCode config - symlink to shared config
  home.file.".config/opencode/opencode.json".source =
    mkOutOfStoreSymlink "${config.home.homeDirectory}/.config/nixos/dotfiles/.config/opencode/opencode.json";

  # Claude Code Router config - routes claude-code to LM Studio on cortex
  home.file.".claude-code-router/config.json".source =
    mkOutOfStoreSymlink "${config.home.homeDirectory}/.config/nixos/dotfiles/.config/claude-code-router/config.json";

  # wayland.windowManager.sway.enable = true;

  # Enable XDG user directories
  # xdg = {
  #   enable = true;
  #   createDirectories = true;
  #   userDirs = {
  #     enable = true;
  #     documents = "Documents";
  #     downloads = "Downloads";
  #     music = "Music";
  #     pictures = "Pictures";
  #     videos = "Videos";
  #   };
  # };
}

